machine("DumpScrolls", { id: "scrolls", at: [0, 0, 1] });
machine("OreBin", { id: "lift1bin", at: [14, 0, -24] });
const skip = machine("Skip", { id: "skip", at: [0, 0, -20] });
skip.joint("SK_Skip_Ore", 1).joint("SK_Skip_Door", 0);
skip.at(0).path([[0, 0, -20], [0, 0, 1]], { speed: 5 })
